<?php
namespace Tests\Feature;
use App\Models\FootballMatch;use App\Models\Team;use App\Services\ApiFootballEnrichmentService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\Http;use Tests\TestCase;
class ApiFootballEnrichmentTest extends TestCase{use RefreshDatabase;
 public function test_epl_fixture_and_lineups_are_saved_for_match_page():void{Cache::flush();config(['services.api_football.key'=>'test-key','services.api_football.url'=>'https://api.test']);$league=\DB::table('leagues')->insertGetId(['football_data_id'=>1,'name'=>'Premier League','short_code'=>'PL','country_code'=>'ENG','created_at'=>now(),'updated_at'=>now()]);$home=Team::create(['football_data_id'=>101,'name'=>'Arsenal FC']);$away=Team::create(['football_data_id'=>102,'name'=>'Everton FC']);$match=FootballMatch::create(['football_data_id'=>5001,'league_id'=>$league,'league_football_data_id'=>1,'home_team_id'=>$home->id,'home_team_football_data_id'=>101,'away_team_id'=>$away->id,'away_team_football_data_id'=>102,'match_date'=>now()->addMinutes(30),'status'=>'SCHEDULED']);Http::fake(['*/fixtures/lineups*'=>Http::response(['response'=>[['team'=>['name'=>'Arsenal'],'formation'=>'4-3-3','coach'=>['name'=>'Coach'],'startXI'=>[['player'=>['id'=>7,'name'=>'A Player','number'=>9,'pos'=>'F']]],'substitutes'=>[]]],'errors'=>[]]),'*/fixtures*'=>Http::response(['response'=>[['fixture'=>['id'=>999],'teams'=>['home'=>['id'=>10,'name'=>'Arsenal'],'away'=>['id'=>20,'name'=>'Everton']]]],'errors'=>[]])]);$result=app(ApiFootballEnrichmentService::class)->syncDate($match->match_date->toDateString());$match->refresh();$this->assertSame(1,$result['matched']);$this->assertSame(999,data_get($match->metadata,'api_football_fixture_id'));$this->assertSame('A Player',data_get($match->metadata,'api_football_lineups.0.starters.0.name'));}
}
